INSERT INTO public.homework_grading_record (id, task_id, file_id, file_name, student_name, score, grade, comment, original_text, status, error_msg, sort, create_time, update_time, creator, updater, deleted) VALUES (1, 1, 20, 'homework-sample.txt', '张三', 95, '优秀', '张三同学对核心概念掌握总体准确：软件生命周期阶段划分基本完整，软件危机表现概括较清晰，数据流图作用表述正确，能体现自顶向下分解和沟通功能。不足是第2题消除途径偏简略，仅提到工程化方法、工具和需求文档，未涉及项目管理、评审测试、原型法、复用与标准化等；表现也可补充成本超支、进度延误、文档缺失等。建议按“表现—原因—对策”结构分点展开，结合教材术语举例说明。第1题可补充阶段迭代与维护地位，第3题可补充DFD在需求分析中建立逻辑模型的作用。', '软件工程学 作业一
姓名：张三 学号：2021010101
1. 简述软件生命周期的主要阶段。
答：软件生命周期包括问题定义、可行性研究、需求分析、总体设计、详细设计、编码、测试、运行与维护。
2. 说明软件危机的表现与消除途径。
答：软件危机表现为进度和成本估计不准、用户不满意、质量不可靠、维护困难。消除途径是采用工程化方法和工具，重视需求分析与文档。
3. 简述数据流图的作用。
答：数据流图用于描述系统的数据流动，可以自顶向下逐层分解，帮助分析人员与用户沟通。', 1, NULL, 0, '2026-09-14 20:36:51.763138', '2026-09-14 20:36:51.763138', NULL, NULL, false);


