INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('e9e0eb53-1f9a-445d-b376-5a095ac5acba', '| 课程代码|01C30109|课程名称|软件工程学|
| ---|---|---|---|
| 英文名称|Software Engineering|Software Engineering|Software Engineering|
| 学时/学分|48学时/ 3学分|其中：实践学时|8学时|
| 课程类型|□通识课  □学科专业基础课  ☑专业课  □集中性实践教学环节|□通识课  □学科专业基础课  ☑专业课  □集中性实践教学环节|□通识课  □学科专业基础课  ☑专业课  □集中性实践教学环节|
| 适用专业|软件工程|修习类别|☑必修      □选修|
| 先修课程|程序设计基础、数据结构、面向对象程序设计、数据库原理<br>及应用|后续课程|系统分析与设计、软件设计与体系结<br>构|
| 课程简介|《软件工程学》是软件工程专业的专业必修课。该课程主要介绍如何把工程化的思<br>想和技术应用于软件系统的开发过程，以及在软件开发过程中必须遵循的基本原理、方	法和工程标准。学生通过本课程的学习，了解软件项目开发和维护的一般过程，以及软件开发中应遵循的最佳实践。同时，通过一个小型软件项目的开发，使学生理论与实践相结合，体会项目开发各阶段所面临的问题，探索相应的解决办法，从而理解软件工程的过程、方法、工具三个要素。为后续课程及今后的软件开发实践打下坚实的基础。|《软件工程学》是软件工程专业的专业必修课。该课程主要介绍如何把工程化的思<br>想和技术应用于软件系统的开发过程，以及在软件开发过程中必须遵循的基本原理、方	法和工程标准。学生通过本课程的学习，了解软件项目开发和维护的一般过程，以及软件开发中应遵循的最佳实践。同时，通过一个小型软件项目的开发，使学生理论与实践相结合，体会项目开发各阶段所面临的问题，探索相应的解决办法，从而理解软件工程的过程、方法、工具三个要素。为后续课程及今后的软件开发实践打下坚实的基础。|《软件工程学》是软件工程专业的专业必修课。该课程主要介绍如何把工程化的思<br>想和技术应用于软件系统的开发过程，以及在软件开发过程中必须遵循的基本原理、方	法和工程标准。学生通过本课程的学习，了解软件项目开发和维护的一般过程，以及软件开发中应遵循的最佳实践。同时，通过一个小型软件项目的开发，使学生理论与实践相结合，体会项目开发各阶段所面临的问题，探索相应的解决办法，从而理解软件工程的过程、方法、工具三个要素。为后续课程及今后的软件开发实践打下坚实的基础。|', '{"title": "表格", "chunkId": "259", "spaceId": "1", "documentId": "28"}', '[-0.124788456,0.03167707,-0.019258218,-0.039396357,-0.050635315,-0.0561948,-0.0030947137,0.040356267,-0.0079142675,0.048275534,0.016888438,-0.020818075,0.015588558,0.039396357,0.034856774,0.03933636,-0.01795834,0.010194057,0.021737989,-0.004714564,0.018978244,-0.039936304,0.01999815,0.0048345528,0.07795279,0.064234056,-0.07939266,0.0026422555,0.014998613,-0.06467402,-0.020898066,-0.01772836,0.059474498,-0.042316087,-0.05503491,-0.0033221927,0.012778818,-0.028737342,-0.07883271,-0.008589205,0.0051745214,-0.0013736229,-0.0047395616,0.0015061107,0.04407592,-0.036816593,-0.038736418,-0.043955933,-0.00875419,0.003449681,-0.030837148,-0.011858903,0.039216373,-0.032377005,0.06771374,-0.0070343493,0.0016460977,0.0047520604,-0.094231285,-0.028917326,-0.06503399,-0.0053995005,-0.02509768,-0.01803833,-0.0040496252,-0.005059532,-0.036956582,-0.0037496532,-0.0068693645,-0.03881641,-0.02713749,-0.02195797,0.04053625,-0.013378763,-0.08575207,0.022357931,-0.0013348765,-0.023977783,-0.01610851,-0.023157857,0.035136748,0.023177857,-0.009199149,0.020538101,-0.03933636,-0.03707657,0.022617908,0.103510424,-0.032257017,-0.02117804,-0.023797799,0.012558838,0.018578282,0.006509398,-0.044915844,-0.038116474,-0.022757895,-0.01984