INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('f6741ec3-29ef-408e-80c1-4bc68d7d670a', '【1】运用软件工程的原理正确地开发出高质量的软件产品，树立软件行业的民族自豪感和爱国主义精神，培养国产软件的创新精神，培养学生团结协作、精益求精、吃苦耐劳、勇于担当、甘于奉献的优秀品质，重视软件质量，提升学生的质量意识，培养大学生理想信念、价值取向、政治信仰、社会责任，培养自主学习能力和终身学习意识，养成勤于反思、乐学善学的习惯，探索求真的科学精神细致严谨，认识到科学实验的重要意义以及实践反作用于理论的辩证关系。', '{"title": "正文", "chunkId": "261", "spaceId": "1", "documentId": "28"}', '[-0.12846893,0.019496115,0.020533467,-0.03112056,-0.082499996,-0.047107983,0.001011291,0.05536612,-0.029961167,0.03386649,-0.0059240935,-0.0027433892,-0.048043635,0.0036332745,0.0487352,0.0035722537,-0.00042936965,0.023737054,0.020167343,-0.035208948,-0.015407728,-0.051664196,0.005212185,0.026605027,0.10788461,0.07338757,-0.039358355,-0.034130916,0.041941565,-0.0046070633,-0.0102972435,0.025242232,0.036734466,-0.051745556,-0.062078398,-0.011522743,0.0027128789,-0.033520706,-0.09144969,-0.006127496,0.021987794,0.006158006,-0.044463754,-0.027235575,0.016221337,-0.046375737,-0.01826553,-0.05731878,-0.049223367,0.029656062,0.016801033,0.029900145,0.028272927,-0.011004067,0.04592825,-0.005369822,-0.013495746,0.021784391,-0.07074334,-0.015397558,-0.01987241,-0.028394967,-0.051745556,-0.010205713,0.004474852,-8.175821e-05,-0.009366678,-0.011441383,-0.015204325,-0.025832098,-0.06386834,0.0104142,-0.017868897,-0.010526071,-0.075665675,0.0071139974,0.0071241674,-0.008593749,0.014736501,-0.015438238,0.014665309,0.02607618,0.021499628,0.03380547,0.016251847,-0.029595042,0.011044747,0.07928623,0.021723371,-0.058661237,-0.045196,-0.00014977087,-0.0074852062,-0.027113533,-0.02166235,0.02591346,-0.020574147,-0.025384612,0.030144228,0.017065458,0.015804363,0.039480396,-0.009956545,-0.024876107,-0.019658837,-0.053047333,0.015438238,0.0072258683,-0.05089127,0.016811205,-0.016699333,0.035107244,0.0010519716,-0.011899037,-0.013272003,0.0036002216,0.028944155,-0.011736316,0.06643121,0.010307414,0.00040076618,-0.010831175,0.031039199,-0.03390717,-0.0012534669,-0.049630173,0.024550663,0.020635169