INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('57e5ed4e-d0aa-4894-8e55-6d76d56ee316', '| 序号|知识单元|教学内容（实验内容）|建议学时|推荐授课形式（实验类型）|支撑课程目标|
