INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('20de8554-1909-423e-9b6f-94f4569f792a', '| 5|实验 2：软件<br>设计|实验内容：软件设计	实验目标：熟悉软件软件总体设计和详细的方法；掌握使用 Visio建立设计模型、软件结构图的设计，使用过程设计的工具的使用，撰写设计文档。<br>重点：软件软件总体设计和详细的方法。	难点：Visio建立设计模型、软件结构图的设计，使用过程设计的工具的使用。	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。|2学时|验证性实验|【1】【2】【3】|
| ---|---|---|---|---|---|
| 6|软件编码和测试|教学要求：了解程序设计语言的选择标准，掌握编码的规范，了解软件测试的基本概念和基础知识，掌握测试中各个步骤的主要功能和测试策略，理解测试准则以及编写实现文档。<br>知识点：<br>1、程序设计风格<br>2、软件测试的基础<br>3、单元测试<br>4、集成测试<br>5、确认测试<br>6、白盒、黑盒测试<br>7、调试<br>8、软件可靠性	重点：程序设计规范、软件测试的几种方法的具体使用规则和使用范围。<br>难点：软件测试的几种方法。	课程思政元素：培养自主学习能力和终身学习意识，养成勤于反思、精益求精、乐学善学的习惯，<br>以提高软件软件质量作为服务目标。|4学时|课堂授课、	讨论与习题讲评|【1】【2】【3】|
| 7|实验 3:软件编码与测试|实验内容：软件编码与测试	实验目标：熟悉软件实现的方法，掌握软件编码的规范与实现，软件单元和集成测试的方法。重点：软件编码的规范、软件测试方法。<br>难点：软件单元和集成测试的方法。	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。|2学时|验证性实验|【1】【2】【3】|', '{"title": "表格", "chunkId": "271", "spaceId": "1", "documentId": "28"}', '[-0.09612545,0.020427639,-0.022092402,-0.014757646,-0.06768736,-0.03104296,-0.0014615651,0.053625,0.003997883,0.042461284,0.011242055,0.0018912213,-0.0018275685,0.044576515,0.037878286,0.05836468,-0.009841695,0.030533737,0.034078706,-0.06760902,-0.023913851,-0.042187087,0.04226543,0.039268855,0.07822434,0.07751926,-0.061498355,-0.027830943,0.032394357,0.02093686,0.0076677087,-0.007780325,0.0054937224,-0.07074269,-0.057150383,-0.035900153,0.009866177,-0.027360892,-0.09064152,0.0028472366,0.023110846,0.02029054,-0.034078706,-0.01319081,0.026969183,-0.023404628,0.0014297388,-0.07853771,-0.037995797,0.011271434,-0.040424395,0.050452154,0.03564554,-0.06529793,0.068588294,-0.0054300698,-0.03215933,0.00036783947,-0.091973335,-0.03505798,-0.056445304,0.010977652,-0.022621209,0.011633765,0.04700511,0.007290689,-0.03928844,-0.010693663,-0.0007063008,-0.014346352,-0.025480688,-0.010762212,0.0401502,0.013964435,-0.08351241,0.0042353566,-0.015335417,-0.035371345,0.007447372,-0.0040933616,0.010488016,0.012201743,-0.01989883,0.0073837196,-0.026851669,-0.01606008,0.0037041006,0.09432359,0.009964105,-0.01240739,-0.044028122,-0.022601625,-0.040737763,-0.028065968,-0.021426497,0.012113608,-0.0056504062,-0.0026097628,0.04430232,0.0037212379,0.004460589,-0.008774287,-0.0151787335,-0.0320614,0.03186555,-0.050961375,0.053625,0.01932106,-0.016148213,-0.013670653,0.02111313,0.034176633,0.01362169,0.010047343,-0.000709361,-0.018508263,0.010869932,-0.0004926968,0.014640134,0.0034445934,0.07712755,0.016001323,0.047240138,-0.047279306,0.00115187,-0.03756492,-0.0022596729,0.05158811,0.016647644,0.03194389,-0.009420607,0.024442658,-0.026949598,0.004379799,-0.03409829,-0.0150906,0.0051999404,0.04105113,-0.045438275,-0.06941088,0.063182704,-0.027145