INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('e5641104-73ed-4ffa-8952-fb3f14ad7ee7', '| 8|软件维护|教学要求：理解维护的概念，掌握各种软件维护的方法。<br>知识点：<br>1、软件维护的定义<br>2、软件维护的特点<br>3、软件的可靠性	重点：软件维护的过程、软件维护的规格说明书的书写规格。<br>难点：软件维护报告书的书写规格。	课程思政元素：培养学生吃苦耐劳、甘于奉献、团结协作的优秀品质。|2学时|课堂授课、	讨论与习题讲评|【1】【2】【3】|
| ---|---|---|---|---|---|
| 9|面向对象方法学与 UML|教学要求：了解面向对象与人的思维过程的关	系，掌握类、对象的概念，三种模型，UML统一建模语言应用以及编写设计文档。<br>知识点：<br>1、面向对象方法学概述及概念<br>2、UML概述<br>3、UML图<br>4、UML的应用<br>重点：UML九种图的设计。<br>难点：UML九种图的设计与应用。<br>课程思政元素：培养学生精益求精、勤于反思，<br>探索求真的科学精神细致严谨。|6学时|课堂授课、	讨论与习题讲评|【1】【4】【5】|
| 10|实验 4：UML图的设计|实验内容：UML图的设计<br>实验目标：熟悉 UML图的设计方法，掌握建模工	具 StartUML的使用，设计 UML的九种图，完成软件项目案例设计。<br>重点：建模工具 StartUML的使用,UML图的设计方法。<br>难点：设计 UML的九种图的方法。	课程思政元素：科学实验的重要意义以及实践反作用于理论的辩证关系；探索求真的科学精神细<br>致严谨、理论对实践的指导意义。|2学时|设计性实验|【1】【2】【3】|', '{"title": "表格", "chunkId": "272", "spaceId": "1", "documentId": "28"}', '[-0.10620459,0.013126521,-0.008004097,-0.031479802,-0.08728491,-0.05087645,-0.00050553505,0.050359737,-0.0029860104,0.013891656,0.012083157,0.026491527,0.012262019,0.05087645,0.019476142,0.039011903,-0.011983789,0.04761718,0.04944555,-0.070114106,-0.017866379,-0.042092312,0.018502334,0.03680593,0.053062547,0.062363397,-0.06864346,-0.011129224,0.02200009,0.025617087,0.004409458,-0.024722775,0.018253913,-0.05886564,-0.028121162,-0.05318179,-0.017150927,-0.034560215,-0.101355426,0.020469822,-0.0024680544,0.004546089,-0.052983053,-0.0016482678,0.031539425,-0.035851996,-0.01515363,-0.04229105,-0.0045113103,-0.04181408,-0.07261818,0.024186186,0.03700467,-0.043682203,0.05616283,-0.030068778,-0.04785566,-0.00064713456,-0.057673227,-0.009951712,-0.06148896,0.005927305,-0.025497846,0.03591162,0.044636134,0.02629279,-0.048650604,0.0059571154,-0.003140031,-0.027107608,-0.017449033,0.010284595,0.036229596,-0.008967968,-0.07583771,0.011546569,-0.01633611,-0.016167184,0.003105252,-0.028041668,0.025199741,0.03893241,0.011944042,0.0064142086,-0.02607418,0.017816694,0.029075095,0.06605989,0.016028069,-0.024464417,-0.007815299,-0.0376605,0.0055745486,-0.025259363,-0.016385794,-0.020887168,-0.025120247,0.015769713,0.04527209,0.034003753,0.01471641,0.013384879,-0.02249693,-0.019267468,-0.0069905436,-0.03917089,0.035116676,0.0073234267,0.015879016,-0.029929662,0.01113916,0.046186276,-0.0034704297,0.0054602753,-0.00022140447,-0.025477972,0.0015662891,-0.025597213,0.021105777,-0.022397563,0.01692238,0.015044325,0.02865775,-0.040780652,0.036885425,-0.048928834,0.015213251,0.022477057,0.03201639,0.06021705,-0.023013644,0.004039312,-0.024941385,0.009743039,-0.044954114,-0.028180784,0.03147