INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('9058b0d9-9c58-4352-b8d0-156dc02b9c65', '| 11|面向对象软	件设计与实现|教学要求：理解面向对象设计原则，掌握面向对象的设计方法，面向对象设计和实现的方法。知识点：<br>1、面向对象分析的基本过程<br>2、需求概述<br>3、建立对象模型、动态模型与功能模型<br>5、面向对象设计<br>6、面向对象系统的实现<br>重点：面向对象分析方法建立的几种模型、面向	对象的设计、面向对象的测试方法、面向对象语言的优点、程序设计风格。<br>难点：面向对象分析方法建立的几种模型、提高设计效率的技术、测试类和集成测试方法的使用<br>范围、测试用例的设计。	课程思政元素：培养精益求精、持之以恒、严谨周到的职业道德、树立目标意识。|2学时|课堂授课、<br>讨论与习题<br>讲评|【1】【2】【3】|
| ---|---|---|---|---|---|
| 12|软件工程技术的发展|教学要求：理解软件重用，掌握 CASE技术、软件开发工具 Rational Rose的使用。<br>知识点：<br>1、CASE技术<br>2、软件工具、软件开发环境<br>3、软件重用<br>4、RUP、Rational  Rose简介<br>5、几种软件构件模型比较	重点：CASE技术、Rational  Rose的使用、几种软件构件模型比较。<br>难点：Rational  Rose的使用、几种软件构件模型。<br>课程思政元素：培养吃苦耐劳、团结协作、勇于担当、甘于奉献的优秀品质。|2学时|课堂授课、	讨论与习题讲评|【1】【4】|
| 13|软件工程管理|教学要求：理解软件开发进度计划,掌握软件项	目管理的管理方法,软件项目人员、配置、质量与风险的管理方法。<br>知识点：<br>1、估算软件规模、工作量估算<br>2、进度计划、人员组织<br>3、质量保证、软件配置管理<br>重点：软件估算的方法、工作量估算的方法、进<br>度计划的书写、项目组成员的组织方式。|2学时|课堂授课、	讨论与习题讲评|【1】【5】|', '{"title": "表格", "chunkId": "273", "spaceId": "1", "documentId": "28"}', '[-0.08845191,0.011124678,-0.021314181,-0.009785236,-0.09102364,-0.039004564,0.005318804,0.048823893,0.014066581,0.027197987,0.013248303,0.01232287,0.014612099,0.04699251,0.032828517,0.06534531,-0.017563744,0.016677275,0.030860754,-0.04718734,-0.003974491,-0.03206869,-0.008168164,0.018547624,0.07948982,0.05451287,-0.038478527,-0.018430728,0.027373333,0.0032195325,0.017729348,-0.00689204,0.05046045,-0.06390358,-0.04286216,-0.04099181,-0.0031903083,-0.016930552,-0.08595811,0.0371537,-0.013102182,0.011397437,-0.032906447,-0.0031537781,0.030042475,-0.04956424,-0.03614059,-0.04274526,-0.016725983,0.006677729,-0.06850152,0.021957114,0.011475368,-0.037484903,0.066826,-0.0007860092,-0.038712323,-0.006765402,-0.08673742,0.0052262605,-0.0655791,0.0020554352,-0.034055933,-0.0015744537,0.031172479,-0.0023781192,-0.026438158,-0.009161786,0.0041327886,-0.023048151,-0.010218728,0.002505975,0.029419025,0.005333416,-0.088218115,-0.002861536,0.007963594,-0.0062832027,-0.018089779,-0.023048151,0.0028420533,0.023437807,0.0071112216,-0.009064372,-0.02889299,0.0090692425,0.024879534,0.08486707,0.014086063,-0.006049409,-0.035127487,-0.0032219677,-0.025444536,-0.025171775,-0.013745114,-0.028074713,-0.054162182,0.023476772,0.034854725,0.023924876,0.009083855,0.0044591255,-0.025580915,-0.014017873,0.0072573423,-0.020573836,0.03974491,-0.017573485,0.0030807175,-0.021080388,0.0080074305,0.037601802,-0.019443832,0.026282296,-0.0066095395,-0.040758014,0.0242366,-0.010988299,0.0047440613,-0.0082850605,0.015683653,0.026925229,0.041030776,-0.05116183,0.0012749056,-0.05361666,0.017407881,0.07080049,0.015829774,0.05264252,0.0041571422,0.023340393,-0.03627697,0.011387696,-0.039569564,-0.012566405,0.0068384623,0.035692487,-0.021567458,-