INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('10a4c491-8610-4c74-81e9-f20ee6743b2a', '利用多媒体、超星学习通、项目演示进行课堂教学，采用具体软件系统的开发项目驱动式教学方法，结合课堂讲授与实验演示，讲解如何运用软件工程学规则软件开发过程，提高软件质量，学生充分参与案例分析、课堂实操练习、上机实验、项目实施等教学过程。注重人工智能在教与学过程中的应用，学生通过 AI提升学习效率和成果。教学中注重与实际软件工程项目或案例相联系，培养学生理论联系实际的能力，以及从实际项目案例中发现问题、分析问题和解决问题的能力。通过超星学习通和中国大学生慕课平台布置学习任务，培养学生自主学习的能力。', '{"title": "正文", "chunkId": "276", "spaceId": "1", "documentId": "28"}', '[-0.09036395,-0.012830421,0.004454734,-0.017326972,-0.096424945,-0.017700864,-0.0031239714,0.07005567,-0.034476835,0.031485695,-0.028888127,0.021252844,-0.002678744,0.025798593,0.032213803,0.03866837,-0.0041177385,0.04057719,0.053486325,-0.065490246,-0.0058445325,-0.023870094,0.011531636,0.049393184,0.09485066,0.03797962,-0.044316117,-0.02855359,0.03801898,-0.027372876,0.019973738,0.030167233,0.015959311,-0.049078327,-0.051164255,-0.043765116,0.003362574,-0.05289597,-0.1011478,0.025129521,0.010050825,-0.009745806,-0.028494556,-0.047936972,0.037487656,-0.046638187,-0.04274183,-0.055808395,-0.019225953,0.019580167,-0.025483735,0.033492908,0.017494239,-0.029301375,0.05423411,-0.012751707,-0.037369587,0.01475892,-0.06245975,0.011935047,-0.050259043,-0.044670332,-0.011895689,0.0068038623,0.01188585,0.036700513,-0.047582757,0.025621485,0.0044990107,-0.010754333,-0.04415869,-0.011659547,0.030521447,0.0016948159,-0.07532953,0.011876011,-0.042899262,-0.04443419,0.03715312,0.0043784794,0.020859273,0.0047622113,-0.0055641127,0.02133156,-0.02310263,-0.031859588,0.030698553,0.09154466,0.013961938,0.0034462078,-0.0508494,-0.014030813,0.013558527,-0.044355474,-0.03868805,-0.0019776954,-0.011462761,-0.016018348,0.023594594,0.035185266,-0.0054214434,-0.001721874,0.019107882,-0.012623796,-0.008348629,-0.019609684,0.02800259,0.0447884,-0.054548968,0.004029185,-0.010547708,0.019649042,0.02133156,0.01994422,-0.01448342,-0.030009804,-0.009947512,0.0072220317,0.04057719,0.015683813,-0.012072797,-0.03087566,0.03923905,-0.0784781,0.0002329142,-0.029557196,0