INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('42bbb02b-a30f-4b57-911d-b529b57221cb', '| 5|实验 2：软件<br>设计|实验内容：软件设计	实验目标：熟悉软件软件总体设计和详细的方法；掌握使用 Visio建立设计模型、软件结构图的设计，使用过程设计的工具的使用，撰写设计文档。<br>重点：软件软件总体设计和详细的方法。	难点：Visio建立设计模型、软件结构图的设计，使用过程设计的工具的使用。	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。|2学时|验证性实验|【1】【2】【3】|
| ---|---|---|---|---|---|
| 6|软件编码和测试|教学要求：了解程序设计语言的选择标准，掌握编码的规范，了解软件测试的基本概念和基础知识，掌握测试中各个步骤的主要功能和测试策略，理解测试准则以及编写实现文档。<br>知识点：<br>1、程序设计风格<br>2、软件测试的基础<br>3、单元测试<br>4、集成测试<br>5、确认测试<br>6、白盒、黑盒测试<br>7、调试<br>8、软件可靠性	重点：程序设计规范、软件测试的几种方法的具体使用规则和使用范围。<br>难点：软件测试的几种方法。	课程思政元素：培养自主学习能力和终身学习意识，养成勤于反思、精益求精、乐学善学的习惯，<br>以提高软件软件质量作为服务目标。|4学时|课堂授课、	讨论与习题讲评|【1】【2】【3】|
| 7|实验 3:软件编码与测试|实验内容：软件编码与测试	实验目标：熟悉软件实现的方法，掌握软件编码的规范与实现，软件单元和集成测试的方法。重点：软件编码的规范、软件测试方法。<br>难点：软件单元和集成测试的方法。	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。|2学时|验证性实验|【1】【2】【3】|', '{"chunkId": "16", "spaceId": "1", "documentId": "1"}', '[-0.07986507,0.021314409,-0.016167855,-0.021432495,-0.069434196,-0.026943143,-0.008044565,0.050343726,0.0009606737,0.040778812,0.006888313,0.0040690247,-0.0017491395,0.03633093,0.046446912,0.05081607,-0.008733396,0.033536244,0.04026711,-0.07116611,-0.02180643,-0.036842633,0.03585859,0.042786263,0.08998105,0.078211874,-0.066049084,-0.02906868,0.038554873,0.018559083,-0.0020000709,-0.0040395036,0.00704084,-0.074551225,-0.057271402,-0.045069247,0.011641249,-0.024778245,-0.093838505,0.0049915668,0.024069734,0.016571313,-0.033634648,-0.0044651027,0.02926549,-0.022239411,0.0074935006,-0.07966826,-0.038358063,0.016187536,-0.024187818,0.05368948,0.030229853,-0.06797781,0.071205474,-0.01276306,-0.028970277,0.00081306696,-0.081951246,-0.034244757,-0.05872779,0.015980886,-0.0073655746,0.018194987,0.0457384,0.0004400525,-0.05282352,-0.00967808,0.0027381044,-0.0035056593,-0.026293674,-0.014701628,0.036173485,0.00834962,-0.078526765,0.004684053,-0.02288888,-0.035051674,0.010863854,0.00176021,0.010608002,0.012261197,-0.018746052,0.013481413,-0.027238358,-0.011139386,0.00286111,0.09399595,0.017033814,-0.020271322,-0.04471499,-0.023735158,-0.043730948,-0.032709647,-0.022514943,0.010234065,-0.00594363,-0.00079769123,0.044793714,0.0023727778,-0.0065488177,-0.013058273,-0.01079497,-0.041054346,0.030052725,-0.038889445,0.07175654,0.023380902,-0.019031424,-0.011749494,0.026273994,0.038515512,0.0074935006,0.0047406354,-0.0065045357,-0.02310537,0.015065725,0.0019225774,0.017899774,0.00638153,0.07577144,0.011168907,0.040345833,-0.038121894,0.0015720114,-0.03276869,-0.0025634365,0.056917146,0.02135377,0.03231603,-0.012989391,0.020369725,-0.032670286,0.015105086,-0.04005062,-0.019031424,-0.005963311,0.037118167,-0.045974568,-0.061089497,0.06057779,-0.039086256