INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('fa6ece4b-16a2-4db2-8d69-b165ea364a53', '| 8|软件维护|教学要求：理解维护的概念，掌握各种软件维护的方法。<br>知识点：<br>1、软件维护的定义<br>2、软件维护的特点<br>3、软件的可靠性	重点：软件维护的过程、软件维护的规格说明书的书写规格。<br>难点：软件维护报告书的书写规格。	课程思政元素：培养学生吃苦耐劳、甘于奉献、团结协作的优秀品质。|2学时|课堂授课、	讨论与习题讲评|【1】【2】【3】|
| ---|---|---|---|---|---|
| 9|面向对象方法学与 UML|教学要求：了解面向对象与人的思维过程的关	系，掌握类、对象的概念，三种模型，UML统一建模语言应用以及编写设计文档。<br>知识点：<br>1、面向对象方法学概述及概念<br>2、UML概述<br>3、UML图<br>4、UML的应用<br>重点：UML九种图的设计。<br>难点：UML九种图的设计与应用。<br>课程思政元素：培养学生精益求精、勤于反思，<br>探索求真的科学精神细致严谨。|6学时|课堂授课、	讨论与习题讲评|【1】【4】【5】|
| 10|实验 4：UML图的设计|实验内容：UML图的设计<br>实验目标：熟悉 UML图的设计方法，掌握建模工	具 StartUML的使用，设计 UML的九种图，完成软件项目案例设计。<br>重点：建模工具 StartUML的使用,UML图的设计方法。<br>难点：设计 UML的九种图的方法。	课程思政元素：科学实验的重要意义以及实践反作用于理论的辩证关系；探索求真的科学精神细<br>致严谨、理论对实践的指导意义。|2学时|设计性实验|【1】【2】【3】|', '{"chunkId": "17", "spaceId": "1", "documentId": "1"}', '[-0.08483543,0.014106079,-9.7768905e-05,-0.038319193,-0.09207748,-0.044208333,-0.0068888995,0.04930164,-0.0051878137,0.013747956,0.0049963174,0.027277058,0.010266201,0.04412875,0.027197475,0.039791476,-0.009256492,0.050296426,0.052843083,-0.073932566,-0.0050361087,-0.034757856,0.008122435,0.034797646,0.067844465,0.057976183,-0.07210216,-0.015956383,0.02829174,0.01909991,-0.0078588165,-0.02021407,0.013668372,-0.07301736,-0.029286528,-0.061756372,-0.013459467,-0.033981923,-0.103537425,0.023278015,0.0052126837,0.011997131,-0.059448466,0.0051977616,0.032390263,-0.036727533,-0.01615534,-0.047192693,-0.0036856856,-0.03477775,-0.055150986,0.02479009,0.037185136,-0.0476304,0.051052466,-0.031674016,-0.036528576,-0.0065805153,-0.049102683,-0.01629461,-0.058533262,0.009157014,-0.015508728,0.044327706,0.044884786,0.015538571,-0.061995123,0.0052773445,0.0025205414,-0.0120866615,-0.013777799,0.0028873691,0.03581233,-0.012753168,-0.07265924,0.0137678515,-0.03324578,-0.018154861,0.0009587259,-0.029027883,0.024431966,0.040686786,0.006490985,0.013131187,-0.027277058,0.021208858,0.029405901,0.061199293,0.018851213,-0.030460376,-0.011479842,-0.03137558,-0.0025690373,-0.02437228,-0.010843177,-0.019637095,-0.024591133,0.011191353,0.03706576,0.03609087,0.005620546,0.011708642,-0.018592568,-0.023258118,-0.0129023865,-0.031872973,0.055668276,0.011499736,0.014503993,-0.023516763,0.0139071215,0.04468583,-0.0012689751,-0.004817256,-0.0045287674,-0.034399733,0.0008200775,-0.020094696,0.028490698,-0.021925105,0.019836051,0.020691568,0.022104166,-0.03067923,0.03469817,-0.044327706,0.013151083,0.029545171,0.031773493,0.06426323,-0.026580706,-0.0014983978,-0.029863503,0.020552298,-0.0508933,-0.03716524,0.0262623