INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('eaa08b1b-e223-45ac-970b-9b8f90abae42', '# 四、课程教学进度计划

<table><tr><td>序号
</td><td>知识单元
</td><td>教学内容（实验内容）
</td><td>建议学时
</td><td>推荐授课形式（实验类型）
</td><td>支撑课程目标
</td></tr><tr><td>1
</td><td>软件工程概述
</td><td>教学要求：了解软件的定义、特点、软件危机产
	生的原因、软件工程，理解软件生命周期、掌握软件开发方法、五种软件开发模型
<br>知识点：
<br>1、软件工程的基本概念、术语
<br>2、软件危机的表现和消除的途径
<br>3、软件生命周期及软件过程
	重点：软件工程相关的基本概念和术语、软件危机的表现和软件工程方法、软件生命周期的模型。
<br>难点：软件生命周期的模型。
	课程思政元素：如何提高国产软件的质量，树立国产民族软件的自豪感，科技报国的家国情怀和使命担当。
</td><td>4学时
</td><td>课堂授课、
