INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('89f376b9-fbb5-467d-af81-88561e425542', '<table><tr><td>2
</td><td>软件计划
</td><td>教学要求：掌握可行性研究的方法，数据流图的绘制、数据字典的编写，状态转换图的建立和应用，数据模型 E-R图设计以及需求规格说明书的
<br>编写。
<br>知识点：
<br>1、可行性研究的任务
<br>2、可行性研究过程
<br>3、系统流程图
<br>4、数据流图、数据字典
<br>5、成本/效益分析
<br>6、可行性研究说明书
	重点：可行性研究的任务、数据流图的画法、数据字典的含义、成本/效益分析的方法、软件计划文档编写。
<br>难点：系统流程图的画法、需求分析方法、数据流图的画法。
	课程思政元素：培养国产软件的创新精神，培养学生精益求精，以提高软件软件质量作为服务目标。
</td><td>4学时
</td><td>课堂授课、
	讨论与习题讲评
</td><td>【1】【2】【3】
</td></tr><tr><td>3
</td><td>实验 1：软件需求分析
</td><td>实验内容：软件需求分析
	实验目标：熟悉软件需求结构化分析的方法，使用 Visio建立数据流、E-R图等，掌握软件需求说明书的撰写。
<br>重点：软件需求结构化分析的方法。
	难点：Visio建立数据流、E-R图、软件需求说明书的撰写。
	课程课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。
</td><td>2学时
