INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('2bbfda58-8be5-45c2-8ea9-ee45013d9b1a', '<table><tr><td>6
</td><td>软件编码和
<br>测试
</td><td>教学要求：了解程序设计语言的选择标准，掌握编码的规范，了解软件测试的基本概念和基础知识，掌握测试中各个步骤的主要功能和测试策略，理解测试准则以及编写实现文档。
<br>知识点：
<br>1、程序设计风格
<br>2、软件测试的基础
<br>3、单元测试
<br>4、集成测试
<br>5、确认测试
<br>6、白盒、黑盒测试
<br>7、调试
<br>8、软件可靠性
	重点：程序设计规范、软件测试的几种方法的具体使用规则和使用范围。
<br>难点：软件测试的几种方法。
	课程思政元素：培养自主学习能力和终身学习意识，养成勤于反思、精益求精、乐学善学的习惯，
<br>以提高软件软件质量作为服务目标。
</td><td>4学时
</td><td>课堂授课、
<br>讨论与习题
<br>讲评
</td><td>【1】【2】【3】
</td></tr><tr><td>7
</td><td>实验 3:软件编码与测试
</td><td>实验内容：软件编码与测试
	实验目标：熟悉软件实现的方法，掌握软件编码的规范与实现，软件单元和集成测试的方法。重点：软件编码的规范、软件测试方法。
	难点：软件单元和集成测试的方法。课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。
</td><td>2学时
</td><td>验证性实验
</td><td>【1】【2】【3】
</td></tr><tr><td>8
</td><td>软件维护
</td><td>教学要求：理解维护的概念，掌握各种软件维护的方法。
<br>知识点：
<br>1、软件维护的定义
<br>2、软件维护的特点
<br>3、软件的可靠性
	重点：软件维护的过程、软件维护的规格说明书的书写规格。
<br>难点：软件维护报告书的书写规格。
<br>课程思政元素：培养学生吃苦耐劳、甘于奉献、
<br>团结协作的优秀品质。
</td><td>2学时
</td><td>课堂授课、
