INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('13796679-ab2a-4818-abeb-4f44e892b365', '<table><tr><td>9
</td><td>面向对象方法学与 UML
</td><td>教学要求：了解面向对象与人的思维过程的关系，掌握类、对象的概念，三种模型，UML统一建模语言应用以及编写设计文档。
<br>知识点：
<br>1、面向对象方法学概述及概念
<br>2、UML概述
<br>3、UML图
<br>4、UML的应用
<br>重点：UML九种图的设计。
<br>难点：UML九种图的设计与应用。
	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨。
</td><td>6学时
</td><td>课堂授课、
<br>讨论与习题
<br>讲评
</td><td>【1】【4】【5】
</td></tr><tr><td>10
</td><td>实验 4：UML图的设计
</td><td>实验内容：UML图的设计
	实验目标：熟悉 UML图的设计方法，掌握建模工具 StartUML的使用，设计 UML的九种图，完成软件项目案例设计。
<br>重点：建模工具 StartUML的使用,UML图的设计方法。
<br>难点：设计 UML的九种图的方法。
	课程思政元素：科学实验的重要意义以及实践反作用于理论的辩证关系；探索求真的科学精神细致严谨、理论对实践的指导意义。
</td><td>2学时
</td><td>设计性实验
</td><td>【1】【2】【3】
</td></tr><tr><td>11
</td><td>面向对象软件设计与实现
</td><td>教学要求：理解面向对象设计原则，掌握面向对象的设计方法，面向对象设计和实现的方法。知识点：
<br>1、面向对象分析的基本过程
<br>2、需求概述
<br>3、建立对象模型、动态模型与功能模型
<br>5、面向对象设计
<br>6、面向对象系统的实现
	重点：面向对象分析方法建立的几种模型、面向对象的设计、面向对象的测试方法、面向对象语
<br>言的优点、程序设计风格。
	难点：面向对象分析方法建立的几种模型、提高设计效率的技术、测试类和集成测试方法的使用
<br>范围、测试用例的设计。
	课程思政元素：培养精益求精、持之以恒、严谨周到的职业道德、树立目标意识。
</td><td>2学时
</td><td>课堂授课、
