INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('2e9b24d2-227e-491e-9793-1dbe962394de', '<table><tr><td>12
</td><td>软件工程技术的发展
</td><td>教学要求：理解软件重用，掌握 CASE技术、软件开发工具 Rational Rose的使用。
<br>知识点：
<br>1、CASE技术
<br>2、软件工具、软件开发环境
<br>3、软件重用
<br>4、RUP、Rational  Rose简介
<br>5、几种软件构件模型比较
	重点：CASE技术、Rational  Rose的使用、几种软件构件模型比较。
<br>难点：Rational  Rose的使用、几种软件构件模型。
<br>课程思政元素：培养吃苦耐劳、团结协作、勇于担当、甘于奉献的优秀品质。
</td><td>2学时
</td><td>课堂授课、
	讨论与习题讲评
</td><td>【1】【4】
</td></tr><tr><td>13
</td><td>软件工程管理
</td><td>教学要求：理解软件开发进度计划,掌握软件项
	目管理的管理方法,软件项目人员、配置、质量与风险的管理方法。
<br>知识点：
<br>1、估算软件规模、工作量估算
<br>2、进度计划、人员组织
<br>3、质量保证、软件配置管理
	重点：软件估算的方法、工作量估算的方法、进度计划的书写、项目组成员的组织方式。
	难点：软件质量的保证、软件的配置管理。课程思政元素：培养学生团结协作、精益求精、勇于担当、甘于奉献的优秀品质，提升学生的质量意识。
</td><td>2学时
</td><td>课堂授课、
<br>讨论与习题
