INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('06c29a49-5e8d-4cfb-9031-6ab5686ba57a', '# 二、课程教学目标

【1】运用软件工程的原理正确地开发出高质量的软件产品，树立软件行业的民族自豪感和爱国主义精神，培养国产软件的创新精神，培养学生团结协作、精益求精、吃苦耐劳、勇于担当、甘于奉献的优秀品质，重视软件质量，提升学生的质量意识，培养大学生理想信念、价值取向、政治信仰、社会责任，培养自主学习能力和终身学习意识，养成勤于反思、乐学善学的习惯，探索求真的科学精神细致严谨，认识到科学实验的重要意义以及实践反作用于理论的辩证关系。

【2】理解软件开发过程中应遵循的流程、准则、标准和规范。

【3】理解从软件工程角度描述需求分析、软件设计、软件测试以及软件开发管理，掌握软件工程各阶段的实现方法。

【4】掌握软件工程的基本概念、基本原理、开发软件项目的工程化的方法和技术。

