INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('2f2a5773-cc09-444f-a67e-5e1c9774c594', '# 四、课程教学进度计划

<table><tr><td>序号
</td><td>知识单元
</td><td>教学内容（实验内容）
</td><td>建议学时
</td><td>推荐授课形式（实验类型）
</td><td>支撑课程目标
</td></tr><tr><td>1
</td><td>软件工程概述
</td><td>教学要求：了解软件的定义、特点、软件危机产
	生的原因、软件工程，理解软件生命周期、掌握软件开发方法、五种软件开发模型
<br>知识点：
<br>1、软件工程的基本概念、术语
<br>2、软件危机的表现和消除的途径
<br>3、软件生命周期及软件过程
	重点：软件工程相关的基本概念和术语、软件危机的表现和软件工程方法、软件生命周期的模型。
<br>难点：软件生命周期的模型。
	课程思政元素：如何提高国产软件的质量，树立国产民族软件的自豪感，科技报国的家国情怀和使命担当。
</td><td>4学时
</td><td>课堂授课、
	讨论与习题讲评
</td><td>【1】【2】
</td></tr></table>

<table><tr><td>2
</td><td>软件计划
</td><td>教学要求：掌握可行性研究的方法，数据流图的绘制、数据字典的编写，状态转换图的建立和应用，数据模型 E-R图设计以及需求规格说明书的
<br>编写。
<br>知识点：
<br>1、可行性研究的任务
<br>2、可行性研究过程
<br>3、系统流程图
<br>4、数据流图、数据字典
<br>5、成本/效益分析
<br>6、可行性研究说明书
	重点：可行性研究的任务、数据流图的画法、数据字典的含义、成本/效益分析的方法、软件计划文档编写。
<br>难点：系统流程图的画法、需求分析方法、数据流图的画法。
	课程思政元素：培养国产软件的创新精神，培养学生精益求精，以提高软件软件质量作为服务目标。
</td><td>4学时
</td><td>课堂授课、
	讨论与习题讲评
</td><td>【1】【2】【3】
</td></tr><tr><td>3
</td><td>实验 1：软件需求分析
</td><td>实验内容：软件需求分析
	实验目标：熟悉软件需求结构化分析的方法，使用 Visio建立数据流、E-R图等，掌握软件需求说明书的撰写。
<br>重点：软件需求结构化分析的方法。
	难点：Visio建立数据流、E-R图、软件需求说明书的撰写。
	课程课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。
</td><td>2学时
</td><td>验证性实验
</td><td>【1】【2】【3】
</td></tr></table>

<table><tr><td>4
</td><td>结构化设计
</td><td>教学要求：了解软件设计的原则与要求，理解软件模块的耦合与内聚，掌握软件结构图的建立，过程设计工具，结构程序设计思想，过程设计工具的应用，程序复杂度的方法以及软件设计文档
<br>编写。
<br>知识点：
<br>1、设计过程与设计原理
	2、启发规则、描绘软件结构的图形工具、面向数据流的设计方法
<br>3、人机界面的设计、结构程序设计
<br>4、过程设计的工具
<br>5、面向数据结构的设计方法
<br>6、程序复杂程度的定量度量
<br>7、详细设计的设计说明书
	重点：描绘总体设计的软件结构的图形化工具、面向数据结构的程序设计方法、程序复杂程度的度量方法、详细设计的设计说明书的规则。
<br>难点：总体设计的目的和设计过程及相关的启发规则、详细设计使用的工具。
	课程思政元素：培养学生团结协作、精益求精、吃苦耐劳、勇于担当、甘于奉献的优秀品质，重视软件质量，提升学生的质量意识。
</td><td>10学时
</td><td>课堂授课、
<br>讨论与习题
<br>讲评
</td><td>【1】【2】【3】
</td></tr><tr><td>5
</td><td>实验 2：软件
<br>设计
</td><td>实验内容：软件设计
<br>实验目标：熟悉软件软件总体设计和详细的方
	法；掌握使用 Visio建立设计模型、软件结构图的设计，使用过程设计的工具的使用，撰写设计文档。
<br>重点：软件软件总体设计和详细的方法。
	难点：Visio建立设计模型、软件结构图的设计，使用过程设计的工具的使用。
	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。
</td><td>2学时
</td><td>验证性实验
</td><td>【1】【2】【3】
</td></tr></table>

<table><tr><td>6
</td><td>软件编码和
<br>测试
</td><td>教学要求：了解程序设计语言的选择标准，掌握编码的规范，了解软件测试的基本概念和基础知识，掌握测试中各个步骤的主要功能和测试策略，理解测试准则以及编写实现文档。
<br>知识点：
<br>1、程序设计风格
<br>2、软件测试的基础
<br>3、单元测试
<br>4、集成测试
<br>5、确认测试
<br>6、白盒、黑盒测试
<br>7、调试
<br>8、软件可靠性
	重点：程序设计规范、软件测试的几种方法的具体使用规则和使用范围。
<br>难点：软件测试的几种方法。
	课程思政元素：培养自主学习能力和终身学习意识，养成勤于反思、精益求精、乐学善学的习惯，
<br>以提高软件软件质量作为服务目标。
</td><td>4学时
</td><td>课堂授课、
<br>讨论与习题
<br>讲评
</td><td>【1】【2】【3】
</td></tr><tr><td>7
</td><td>实验 3:软件编码与测试
</td><td>实验内容：软件编码与测试
	实验目标：熟悉软件实现的方法，掌握软件编码的规范与实现，软件单元和集成测试的方法。重点：软件编码的规范、软件测试方法。
	难点：软件单元和集成测试的方法。课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨、理论对实践的指导意义。
</td><td>2学时
</td><td>验证性实验
</td><td>【1】【2】【3】
</td></tr><tr><td>8
</td><td>软件维护
</td><td>教学要求：理解维护的概念，掌握各种软件维护的方法。
<br>知识点：
<br>1、软件维护的定义
<br>2、软件维护的特点
<br>3、软件的可靠性
	重点：软件维护的过程、软件维护的规格说明书的书写规格。
<br>难点：软件维护报告书的书写规格。
<br>课程思政元素：培养学生吃苦耐劳、甘于奉献、
<br>团结协作的优秀品质。
</td><td>2学时
</td><td>课堂授课、
	讨论与习题讲评
</td><td>【1】【2】【3】
</td></tr></table>

<table><tr><td>9
</td><td>面向对象方法学与 UML
</td><td>教学要求：了解面向对象与人的思维过程的关系，掌握类、对象的概念，三种模型，UML统一建模语言应用以及编写设计文档。
<br>知识点：
<br>1、面向对象方法学概述及概念
<br>2、UML概述
<br>3、UML图
<br>4、UML的应用
<br>重点：UML九种图的设计。
<br>难点：UML九种图的设计与应用。
	课程思政元素：培养学生精益求精、勤于反思，探索求真的科学精神细致严谨。
</td><td>6学时
</td><td>课堂授课、
<br>讨论与习题
<br>讲评
</td><td>【1】【4】【5】
</td></tr><tr><td>10
</td><td>实验 4：UML图的设计
</td><td>实验内容：UML图的设计
	实验目标：熟悉 UML图的设计方法，掌握建模工具 StartUML的使用，设计 UML的九种图，完成软件项目案例设计。
<br>重点：建模工具 StartUML的使用,UML图的设计方法。
<br>难点：设计 UML的九种图的方法。
	课程思政元素：科学实验的重要意义以及实践反作用于理论的辩证关系；探索求真的科学精神细致严谨、理论对实践的指导意义。
